    # ---------------- appendix 7
    AQ(7, ['חברת ״דלתא ים״ צופה לקבל תקבול של 600,000 ש״ח בעוד 5 שנים. החל ממועד זה יתקבל התקבול אחת לשנה עד אינסוף, כאשר התקבולים צפויים לצמוח בשיעור קבוע של 3% לשנה. הריבית השנתית היא 7%. מהו הערך הנוכחי של סדרת התקבולים? התשובות מוצגות ברמת דיוק של ספרה אחת לאחר הנקודה.'],
       ['15.0 מיליון ש״ח', '11.4 מיליון ש״ח', '10.7 מיליון ש״ח', '8.6 מיליון ש״ח', '20.0 מיליון ש״ח'], 1, '$15,000,000 × (1.07)^{-4} = 11,443,428.18$. נושא: סדרה צומחת אינסופית דחויה. מלכודת: היוון של 5 תקופות במקום 4.')
    AS(7, 'ב', ['<b>זיהוי:</b> זרם אינסופי, שהתזרים בו צומח בשיעור קבוע, ובנוסף הוא דחוי. שלושה מרכיבים, ונטפל בהם לפי הסדר.',
                '<b>שלב 1, הנוסחה.</b> בצמיתות צומחת, הריבית שבמכנה מוחלפת בהפרש שבין הריבית לשיעור הצמיחה. במונה מוצב התזרים הראשון בלבד.',
                '=PV_{4} = \\f{600,000}{0.07 - 0.03} = \\f{600,000}{0.04} = 15,000,000',
                '<b>שלב 2, לאיזו נקודת זמן הגענו.</b> כמו בכל סדרה, הנוסחה מובילה תקופה אחת לפני התזרים הראשון. התזרים הראשון בזמן 5, ולכן התוצאה 15,000,000 היא הערך בזמן 4.',
                '<b>שלב 3, ההתאמה.</b> מהוונים 4 שנים אחורה.',
                '=PV_{0} = 15,000,000 × (1.07)^{-4} = 11,443,428.18'],
       'ב. כ-11.4 מיליון ש״ח.', [('trap', 'תשובה א היא עצירה בשלב 1, בלי היוון בכלל. תשובה ג מתקבלת מהיוון של 5 שנים במקום 4, כלומר היוון כפול. שימו לב עד כמה הכלל זהה לזה של סדרה רגילה: הצמיחה שינתה את המכנה, אבל לא שינתה דבר בעניין נקודת היעד.')],
       tl=TL([0, 1, 2, 3, 4, 5, 6, '...'], flows={5: '600,000', 6: '618,000'}, marks={0: 'PV = ?'}, moves=[dict(a=5, b=4, t='', s=4), dict(a=4, b=0, t='× (1.07)^{-4}', s=6)]), split=3)

